input.command:
cat > /tmp/opencode/check404c.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium, devices } = require('playwright');
const config = JSON.parse(require('fs').readFileSync(join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime,'display'),'utf8').trim();
const browser = await chromium.launch({...config.browser.launchOptions, timeout:30000});
const context = await browser.newContext({ viewport:{width:844,height:390}, deviceScaleFactor:2, isMobile:true, hasTouch:true, userAgent: devices['iPhone 13'].userAgent });
const page = await context.newPage();
page.on('console', m => { if(m.type()==='error') console.log('CONSOLE', m.text(), m.location()); });
page.on('requestfailed', r => console.log('FAILED', r.url(), r.failure()?.errorText));
page.on('response', r => { if (r.status() >= 400) console.log('RESP', r.status(), r.url()); });
await page.goto('http://localhost:3002', {waitUntil:'load'});
await page.waitForSelector('#start-screen:not(.hidden)', {timeout:20000});
await page.waitForTimeout(3000);
await browser.close();
EOF
cd /tmp/opencode && node check404c.mjs
